using TeamsAgent.Core;
using Xunit;
namespace TeamsAgent.Tests;
public class ReviewRegressionTests
{
    [Fact] public async Task RequestAcceptedDoesNotConfirmRecording() { var t = new Transport(); var gate = new RecordingGate(); var task = new RecordingConfirmation(t).StartAsync("call", gate, default); await t.PollStarted.Task.WaitAsync(TimeSpan.FromSeconds(1)); Assert.False(gate.CanPersist); t.Result.SetResult(new("location", "completed")); await task; Assert.True(gate.CanPersist); }
    [Fact] public async Task FailedRecordingOperationCannotOpenGate() { var t = new Transport(); t.Result.SetResult(new("location", "failed")); var gate = new RecordingGate(); await Assert.ThrowsAsync<InvalidOperationException>(() => new RecordingConfirmation(t).StartAsync("call", gate, default)); Assert.False(gate.CanPersist); }
    [Fact] public void LobbyOnlyUserDidNotAttend() => Assert.False(Attendance.ActuallyAttended(true, false));
    [Fact] public void UnknownLobbyStateIsNotAttendee() => Assert.False(Attendance.ActuallyAttended(null, false));
    [Fact] public void AdmittedUserDidAttend() => Assert.True(Attendance.ActuallyAttended(false, false));
    [Fact] public void DeletedSessionIsNeverResurrected() => Assert.Throws<KeyNotFoundException>(() => SessionCallbacks.Existing(null, DateTimeOffset.UtcNow));
    [Fact] public void ExpiredSessionCannotBeRevived() { var s = new MeetingSession { Key = new(Guid.NewGuid(), "m"), OrganizerId = Guid.NewGuid(), Join = new("u", "t", Guid.NewGuid()), Created = DateTimeOffset.UtcNow.AddDays(-31) }; Assert.Throws<InvalidOperationException>(() => SessionCallbacks.Existing(s, DateTimeOffset.UtcNow)); }
    [Fact] public async Task TerminalBeforeEstablishedCannotStart() { var life = new RuntimeLifecycle(); var starts = 0; await life.FinishAsync(() => Task.CompletedTask); await life.StartAsync(_ => { starts++; return Task.CompletedTask; }); Assert.Equal(0, starts); }
    [Fact] public async Task PendingConfirmationCannotResumeAfterTermination() { var life = new RuntimeLifecycle(); var entered = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously); var capturing = false; var start = life.StartAsync(async ct => { entered.SetResult(); await Task.Delay(Timeout.Infinite, ct); capturing = true; }); await entered.Task; await life.FinishAsync(() => Task.CompletedTask); await Assert.ThrowsAnyAsync<OperationCanceledException>(() => start); Assert.False(capturing); }
    [Fact] public async Task FinalSpeechWritesAreAwaitedAfterSessionStop() { var completion = new RecognitionCompletion(); var write = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously); completion.Add(() => write.Task); completion.End(); var finished = completion.CompleteAsync(default); Assert.False(finished.IsCompleted); write.SetResult(); await finished; Assert.False(completion.Add(() => throw new Exception("Late callback persisted"))); }
    [Fact] public async Task RosterCallbacksCannotWriteAfterFinalSnapshot() { var drain = new AsyncResultDrain(); var writes = 0; drain.Add(() => { writes++; return Task.CompletedTask; }); await drain.SealAndDrainAsync(); Assert.False(drain.Add(() => { writes++; return Task.CompletedTask; })); Assert.Equal(1, writes); }
    sealed class Transport : IRecordingStatusTransport { public TaskCompletionSource PollStarted = new(TaskCreationOptions.RunContinuationsAsynchronously); public TaskCompletionSource<RecordingOperation> Result = new(TaskCreationOptions.RunContinuationsAsynchronously); public Task<RecordingOperation> RequestAsync(string c, bool r, CancellationToken ct) => Task.FromResult(new RecordingOperation("location", "running")); public Task<RecordingOperation> PollAsync(RecordingOperation o, CancellationToken ct) { PollStarted.TrySetResult(); return Result.Task.WaitAsync(ct); } }
}
